package auth

import (
	"context"
	"errors"
	"log/slog"
	"strings"
	"sync"
	"time"

	"golang.org/x/sync/singleflight"
)

// ApprovalVerdict is the outcome of an account-approval check (COR-940). It
// mirrors entire-core's management-plane gate: 403 only on a confirmed deny,
// retryable on a lookup failure (COR-631 — an unavailable credential is not a
// verdict).
type ApprovalVerdict int

const (
	VerdictApproved ApprovalVerdict = iota
	VerdictWaitlisted
	VerdictUnavailable
)

// ErrAccountNotFound is the lookup's signal that no account row exists (a reaped
// account) — treated as waitlisted, fail closed. The wiring adapter maps
// coreapi's not-found to this so the auth package stays free of the coreapi
// import; any other lookup error is unavailable.
var ErrAccountNotFound = errors.New("auth: account not found")

// serviceAccountPrefix marks machine identities, out of the waitlist by
// construction (provisioned by an approved org manager), so the checker approves
// them without a lookup — mirroring core's IsServiceAccount carve-out.
const serviceAccountPrefix = "svc_"

const (
	defaultApprovalTTL = 60 * time.Second
	// approvalCacheMax hard-caps the verdict cache. Expiry cleanup happens on read
	// (see cached), so this only bounds a churn of distinct callers whose entries
	// are never re-read; a per-region API stays well under it.
	approvalCacheMax = 16384
)

// ApprovalLookup fetches an account's live approved flag. A nil *bool means the
// account exists but Core predates the approved field; ErrAccountNotFound means
// no such account; any other error is a lookup failure.
type ApprovalLookup func(ctx context.Context, accountID string) (*bool, error)

// ApprovalChecker resolves an account's waitlist state for the authenticated
// HTTP surface, backed by a live Core lookup behind a short TTL cache. It is a
// process singleton (one lookup client), safe for concurrent use. Approved and
// waitlisted verdicts are cached for the TTL; an unavailable verdict is never
// cached, so a transient Core blip resolves on the next request.
type ApprovalChecker struct {
	lookup ApprovalLookup
	ttl    time.Duration

	mu    sync.Mutex
	cache map[string]cachedVerdict

	// flight collapses concurrent cold-cache lookups for one account into a
	// single outbound call (a request fan-out otherwise stampedes Core).
	flight singleflight.Group
}

type cachedVerdict struct {
	verdict ApprovalVerdict
	expiry  time.Time
}

// NewApprovalChecker builds a checker over lookup. A non-positive ttl defaults
// to defaultApprovalTTL.
func NewApprovalChecker(lookup ApprovalLookup, ttl time.Duration) *ApprovalChecker {
	if ttl <= 0 {
		ttl = defaultApprovalTTL
	}
	return &ApprovalChecker{
		lookup: lookup,
		ttl:    ttl,
		cache:  make(map[string]cachedVerdict),
	}
}

// Check resolves accountID's approval verdict, serving a fresh cached entry when
// present.
func (c *ApprovalChecker) Check(ctx context.Context, accountID string) ApprovalVerdict {
	if strings.HasPrefix(accountID, serviceAccountPrefix) {
		return VerdictApproved
	}
	if v, ok := c.cached(accountID); ok {
		return v
	}
	v, _, _ := c.flight.Do(accountID, func() (any, error) {
		if v, ok := c.cached(accountID); ok {
			return v, nil
		}
		// Detach the leader's request context: collapsed followers share this one
		// lookup, so a leader disconnecting mid-flight must not cancel it and turn
		// every waiter's verdict into a spurious VerdictUnavailable.
		verdict := c.resolve(context.WithoutCancel(ctx), accountID)
		if verdict != VerdictUnavailable {
			c.store(accountID, verdict)
		}
		return verdict, nil
	})
	return v.(ApprovalVerdict)
}

// resolve maps a live lookup to a verdict.
func (c *ApprovalChecker) resolve(ctx context.Context, accountID string) ApprovalVerdict {
	approved, err := c.lookup(ctx, accountID)
	switch {
	case errors.Is(err, ErrAccountNotFound):
		return VerdictWaitlisted
	case err != nil:
		slog.WarnContext(ctx, "auth: approval lookup failed", slog.String("account_id", accountID), slog.String("error", err.Error()))
		return VerdictUnavailable
	case approved == nil:
		// Core predates the approved field; allow until it ships. The cache
		// bounds this warning to once per account per TTL.
		slog.WarnContext(ctx, "auth: approval flag absent, allowing", slog.String("account_id", accountID))
		return VerdictApproved
	case *approved:
		return VerdictApproved
	default:
		return VerdictWaitlisted
	}
}

// cached returns accountID's live verdict, evicting the entry when it has
// expired so a stale read cleans up after itself instead of leaving the key for
// a later sweep.
func (c *ApprovalChecker) cached(accountID string) (ApprovalVerdict, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()
	e, ok := c.cache[accountID]
	if !ok {
		return 0, false
	}
	if time.Now().After(e.expiry) {
		delete(c.cache, accountID)
		return 0, false
	}
	return e.verdict, true
}

func (c *ApprovalChecker) store(accountID string, v ApprovalVerdict) {
	c.mu.Lock()
	defer c.mu.Unlock()
	// Hard-cap the cache: once full, drop an arbitrary entry to make room. The
	// evicted account just re-resolves on its next request — a cache miss, never a
	// wrong verdict. store only ever inserts a new key (a hit returns before it,
	// and cached evicts an expired key before the miss), so this bounds len.
	if len(c.cache) >= approvalCacheMax {
		for k := range c.cache {
			delete(c.cache, k)
			break
		}
	}
	c.cache[accountID] = cachedVerdict{verdict: v, expiry: time.Now().Add(c.ttl)}
}
