		repoDeps.AnonClusterAudience = anonAudience
		log.InfoContext(ctx, "anonymous public-repo access enabled", "issuer", cfg.AnonIssuer)
	}
	// Approval gate, wired from the internal-mTLS Core client below and shared by
	// the repo- and user-activity surfaces. nil without internal mTLS (local dev),
	// which leaves the authenticated surface ungated.
