	var coreInternalHTTPClient *http.Client
	// coreClient is hoisted out of the if-block below (rather than local to
	// it) so the gate/stale recompute wiring further down — which needs it
	// for the checks gate's installation-token forge and approvals'
	// self-approval-exclusion login resolve, same as the repo-activity
	// worker's identical wiring in server.go — can still reach it. nil
	// without internal mTLS (local dev), same condition every other user of
	// this client already degrades on.
	var coreClient *coreapi.Client
	if coreReloader != nil {
		coreInternalHTTPClient = authmtls.NewClient(coreReloader)
		// Serve-time author-identity resolution reads near-static entire-core records —
		// account ULID → GitHub login (firstCommitAuthorUsername, contributor/session
		// panels) and git author email → login (commitAuthorUsername) — through
		// process-local caches rather than hitting entire-core on every request.
		coreClient = coreapi.New(cfg.CoreInternalURL, coreInternalHTTPClient)
		repoDeps.AuthorUsernames = httpapi.NewCachedAuthorUsernameResolver(coreClient)
		repoDeps.AuthorEmails = httpapi.NewCachedAuthorEmailResolver(coreClient)
		// Repo collaborators pass-through (GET /repos/{repo_id}/collaborators): the
		// BFF's author-filter picker, resolved live per request (small, repo-scoped
		// principal sets — no caching, unlike the author resolvers above).
		repoDeps.RepoCollaborators = coreClient
		repoDeps.RepoGroups = coreClient
		// "@username" actor references on trail writes resolve to account ids
		// through Core (ENT-2922); only the id is stored.
		repoDeps.ActorAccounts = coreClient
		// Waitlist gate (COR-940): resolve the caller's live approved flag from the
		// same internal-mTLS account read, mapping a not-found account to the fail-
		// closed sentinel so a reaped account reads as waitlisted, not unavailable.
		approval = auth.NewApprovalChecker(func(ctx context.Context, accountID string) (*bool, error) {
			acct, err := coreClient.AccountByID(ctx, accountID)
			if errors.Is(err, coreapi.ErrNotFound) {
				return nil, auth.ErrAccountNotFound
			}
			if err != nil {
				return nil, err
			}
			return acct.Approved, nil
		}, 0)
		repoDeps.Approval = approval
		// /me foreign-repo name resolution: name rows for a repo with no placement in
		// this cell (which otherwise render as a bare ULID) by forwarding the caller's
		// bearer to Core, per-user gated and shown-not-stored. Best-effort — a Core
		// miss/timeout leaves the row bare — and Core is called only when a render has
		// unresolved foreign rows, so it is always on (no gate). Over the shared
		// internal mTLS pipe, otel-instrumented like every other Core hop; never the
		// workload cert as the authorization (same forward-the-bearer rule as the gateway).
		coreTransport := otelhttp.NewTransport(coreReloader)
		repoDeps.ForeignRepoNames = httpapi.NewCoreForeignRepoNames(cfg.CoreInternalURL, coreTransport, log)
		projectResolver := httpapi.NewCoreProjectRouteResolver(cfg.CoreAPIURL, cfg.CoreInternalURL, coreTransport)
		repoDeps.ProjectRoutes = projectResolver
	} else {
		log.WarnContext(ctx, "core client: internal mTLS not configured; firstCommitAuthorUsername falls back to stored GitHub login, commitAuthorUsername resolves to null, and the waitlist approval gate is disabled")
		// Without internal mTLS, project ID-to-name resolution fails closed.
		repoDeps.ForeignRepoNames = httpapi.NewCoreForeignRepoNames(cfg.CoreAPIURL, nil, log)
		projectResolver := httpapi.NewCoreProjectRouteResolver(cfg.CoreAPIURL, "", nil)
		repoDeps.ProjectRoutes = projectResolver
	}

// enforceApproval applies the waitlist gate to an already-authenticated caller
// (COR-940), returning true — after writing the response — when the request must
// not proceed. A nil checker is a no-op. Fail-closed: only an explicit approved
// verdict passes; waitlisted is 403, and anything else (unavailable, or a future
// verdict) is a retryable 503.
func enforceApproval(api huma.API, ctx huma.Context, approval *auth.ApprovalChecker, reqCtx context.Context, accountID string) bool {
	if approval == nil {
		return false
	}
	switch approval.Check(reqCtx, accountID) {
	case auth.VerdictApproved:
		return false
	case auth.VerdictWaitlisted:
		_ = huma.WriteErr(api, ctx, http.StatusForbidden, "waitlisted: your account is pending approval")
	default: // VerdictUnavailable, or any future verdict → fail closed, retryable
		_ = huma.WriteErr(api, ctx, http.StatusServiceUnavailable, "approval check temporarily unavailable")
	}
	return true
}

// jwksRetryAfter is in seconds.
const jwksRetryAfter = "5"

// writeAuthnErr answers a JWKS outage with 503, else 401.
func writeAuthnErr(api huma.API, ctx huma.Context, err error) {
	if errors.Is(err, auth.ErrJWKSUnavailable) {
		// The cause can name the JWKS URL.
		ctx.SetHeader("Retry-After", jwksRetryAfter)
		_ = huma.WriteErr(api, ctx, http.StatusServiceUnavailable, "authentication temporarily unavailable")
		return
	}
	_ = huma.WriteErr(api, ctx, http.StatusUnauthorized, "authentication required", err)
}

