	if project.ID != p.ProjectID {
		return nil, nil
	}
	host, name := "et", project.Name
	switch p.Forge {
	case coreapi.RepoForgeEntire:
		// Native public names are directory names. This preserves repo-only
		// readers without requiring a project-wide public lookup.
	case coreapi.RepoForgeGitHub:
		host = "gh"
		var ok bool
		name, _, ok = strings.Cut(p.FullName, "/")
		if !ok || !validProjectRouteName(host, name) {
			return nil, nil
		}
		if automationCaller(ctx) {
			// Core's public resolve rejects automation principals. The owner comes
			// from the parent's own backing repo in this cell, so it can be stale.
			if !strings.HasPrefix(project.Name, "gh:mirrors:") {
				return nil, nil
			}
		} else {
			referenced, err := cachedParentProject(references, host+"/"+strings.ToLower(name), func() (ProjectRoute, error) {
				route, err := routes.ByReference(ctx, host, name)
				if coreUnauthorized(err) {
					// The caller authenticated here; Core declining its bearer leaves
					// the parent unresolved rather than failing the authorised read.
					slog.WarnContext(ctx, "trails: parent project reference unauthorized; parent unresolved",
						slog.String("owner", name), slog.Any("err", err))
					return route, coreapi.ErrNotFound
				}
				return route, err
			})
			if err != nil || referenced == nil {
				return nil, err
			}
			// A stale repository name may now name someone else's namespace.
			// Only Core's canonical resolution to THIS parent project admits it.
			if referenced.ID != p.ProjectID {
				return nil, nil
			}
			name = referenced.Name
		}
	default:
		return nil, nil
	}
	if !validProjectRouteName(host, name) {
		return nil, nil
	}
	return &TrailParentReference{
		ID: p.ID, Number: p.Number, ProjectID: p.ProjectID,
		Host: host, Project: strings.ToLower(name), Path: projectTrailPath(host, name, p.ID),
		Jurisdiction: project.Jurisdiction, PrimaryProcessingCell: project.PrimaryProcessingCell,
	}, nil
}

func automationCaller(ctx context.Context) bool {
	id := auth.FromContext(ctx)
	if id == nil {
		return false
	}
	_, ok := id.Subject.Automation()
	return ok
}

