package auth

import (
	"context"
	"errors"
	"fmt"

	"github.com/entirehq/entiredb/modules/authz"
)

// AccessChecker is the per-request authorization decision-point for the
// read API. It wraps the caller's Identity with the process-shared
// authz.Reader (github.com/entirehq/entiredb/modules/authz) — a read-only
// client for the regional read-only SpiceDB — and exposes two shapes of
// check:
//
//   - HasPermission(type, id, perm) and the bounded RepoIDs* bulk checks
//     (Reader.Can / Reader.BulkCan) for gates and read filters that already
//     know their candidate ids — O(candidates), no enumerate-the-universe.
//   - MemberRepoSet(): the set of repos the caller is a member of
//     (Reader.List repo/list) — a direct grant or a project they belong to,
//     excluding the public_viewer wildcard and platform cascade — for the
//     /cache/prs discovery enumeration. repo/list carries no wildcard, so its
//     reverse walk is bounded by what the caller actually belongs to. The
//     pull set is never enumerated: repo#pull carries the account:* public
//     wildcard, so a reverse walk returns every public repo on the cell
//     (COR-1369) — pull is answered by point checks only.
//   - DiscoverProjectSet(): the project/discover enumeration for project Trail
//     lists, including forge membership as Core's project catalog does.
//
// The subject is always derived from the verified Identity
// (authz.AccountSubject(identity.AccountID)) — never from request input. The
// read-only key can query ANY account, so taking the account id from anything
// but the authenticated caller would be a confused-deputy hole.
//
// Lifecycle: the *authz.Reader holds a gRPC connection and is a process
// singleton (dialed once at startup); one AccessChecker wraps it per HTTP
// request, holds no state beyond the identity, and fails closed on Reader
// errors — never return data when the access lookup failed.
type AccessChecker struct {
	identity *Identity
	reader   *authz.Reader
}

// NewAccessChecker builds an AccessChecker bound to id, backed by the shared
// authz.Reader. reader is the process singleton dialed at startup
// (server.RunActivityAPI) — do NOT dial per request; the Reader holds a gRPC
// connection. Returns an error if id or reader is nil.
func NewAccessChecker(id *Identity, reader *authz.Reader) (*AccessChecker, error) {
	if id == nil {
		return nil, errors.New("auth: AccessChecker requires Identity")
	}
	if reader == nil {
		return nil, errors.New("auth: AccessChecker requires authz.Reader")
	}
	return &AccessChecker{
		identity: id,
		reader:   reader,
	}, nil
}

