)

// defaultLookupTimeout caps each upstream RepoLookup RPC. It applies inside
// the singleflight slot on a detached context so one caller cancelling can't
// kill an in-flight lookup that other callers are coalesced onto.
const defaultLookupTimeout = 10 * time.Second

// defaultSweepInterval is how often Run scans the entry map for expired
// entries. Lookups already evict on read; the sweeper exists only to drop
// one-shot keys that never get re-read so memory stays bounded over the
// process lifetime.
const defaultSweepInterval = 5 * time.Minute

// CachingRepoLookupClient wraps a RepoLookupClient with a read-through in-memory
// cache keyed on (provider, owner, repo, github_repo_id).
//
// Positive responses live for PosTTL; empty ("no placements") responses live
// for NegTTL, kept short on purpose — a stale negative entry silently delays
// mirror activation when a user wires a new repo in entire-core. A stale
// positive entry can also route pushes to a previously-placed cluster for up
// to PosTTL after a re-placement, but mirror moves are rare and worst case
// we route to the prior cluster set briefly; an outage of the wrong cluster
// is far costlier than a few seconds of stale routing.
//
// Concurrent misses on the same key are coalesced via singleflight so a push
// burst on a cold key fans to a single upstream RPC. Errors are never cached.
//
// The upstream RPC runs on a detached context (the leader's caller cancelling
// would otherwise propagate to every coalesced waiter and silently drop a
// burst of webhook routes). Each caller selects on its own ctx so an
// individual cancellation only affects that caller.
//
// On error the leader retries once inside the same singleflight slot before
// broadcasting, so all coalesced waiters share the retry. Caps upstream
// fanout at 2 RPCs per burst regardless of waiter count — a retry done in
// the outer code would race against late waiters spawning new singleflight
// slots once the first one drains.
type CachingRepoLookupClient struct {
	inner         RepoLookupClient
	posTTL        time.Duration
	negTTL        time.Duration
	lookupTimeout time.Duration
	sweepInterval time.Duration
	now           func() time.Time

	entries sync.Map // map[string]*cacheEntry
	group   singleflight.Group
}

type cacheEntry struct {
	placements []*repolookupv1.Placement
	expiresAt  time.Time
}

// lookupOutcome is the value singleflight broadcasts to all coalesced
// waiters: the placements plus whether the leader had to retry. Carrying
// retried through the singleflight result is what makes all waiters see the
// same telemetry (a shared call shares its outcome).
type lookupOutcome struct {
	placements []*repolookupv1.Placement
	retried    bool
}

// NewCachingRepoLookupClient builds a cache around inner. A zero posTTL or
// negTTL disables caching for that class of response (the call always falls
// through to inner).
func NewCachingRepoLookupClient(inner RepoLookupClient, posTTL, negTTL time.Duration) *CachingRepoLookupClient {
	return &CachingRepoLookupClient{
		inner:         inner,
		posTTL:        posTTL,
		negTTL:        negTTL,
		lookupTimeout: defaultLookupTimeout,
		sweepInterval: defaultSweepInterval,
		now:           time.Now,
	}
}

