// Source of truth lives in the entiredb repository; this copy exists so
// mirror-pipeline can generate its own Connect client stubs without taking
// a Go-module dependency on the entire entiredb tree. Keep the proto package
// name (repolookup.v1) byte-for-byte identical with entiredb's copy — it
// determines the on-the-wire RPC path and any drift silently breaks calls.
//
// When entiredb's proto changes, copy the new file here and run
// `mise run protobuf`. CI should fail loudly the day a renamed field lands
// upstream.

syntax = "proto3";

package repolookup.v1;

option go_package = "github.com/entirehq/mirror-pipeline/gen/proto/repolookup/v1;repolookupv1";

service RepoLookup {
  // LookupByMirror resolves upstream mirror coordinates to every routable
  // placement that hosts a mirror of them. An upstream may be mirrored in
  // multiple jurisdictions/clusters; the response carries the full list,
  // ordered by (jurisdiction, cluster_slug).
  //
  // Placements without a cluster_slug (legacy rows still in the COR-138
  // backfill window) are filtered server-side and logged at warn level —
  // they are not addressable on per-cluster NATS subjects, so returning
  // them would silently route work nowhere. An empty response means no
  // routable mirror exists; it does not distinguish "no mirror at all"
  // from "all mirrors are still unstamped."
  rpc LookupByMirror(LookupByMirrorRequest) returns (LookupByMirrorResponse);

  // LookupMirrorByID is LookupByMirror's inverse: given a mirror's EntireDB
  // repo ULID, return the upstream coordinates (provider/owner/repo) it
  // mirrors. Callers that hold only the mirror_repos id — e.g. a consumer of a
  // resource_lifecycle_v1 mirror.created event, whose payload is a thin
  // resource_id-only projection — use it to recover the (owner, repo) they
  // need to act on the mirror (COR-717: seed github_repo_meta on mirror
  // creation). Returns CodeNotFound when no mirror_repos row matches the id (or
  // the placement is suspended); CodeInvalidArgument when repo_id is empty or
  // not a valid ULID.
  rpc LookupMirrorByID(LookupMirrorByIDRequest) returns (LookupMirrorByIDResponse);

  // LookupNativeMirrorsByRepoID resolves a repo id (any placement of a native
  // repo — primary or native mirror; the id a repo_refs_v1 ref event carries) to
  // its group's git-data HOME placement and every REPLICATION-eligible
  // native-mirror placement (ADR 20260720-native-mirroring). Replica fan-out
  // consumes this: it drops the event unless its local cluster is the home
  // (loop prevention), then publishes one sync job per native mirror.
  // source_url is the home cluster's INTERNAL by-ID git URL, computed here so
  // fanout and the worker stay source-agnostic; it is never user-facing.
  //
  // Native mirrors below the serving stage (still being created), suspended, or
  // marked for deletion are excluded. Placements that ARE listed may still hold
  // an empty or partially-synced repo — a placement is listed from the moment
  // it is registered, and that replication traffic is what makes it converge,
  // so this response is not a statement that a mirror can serve READS. Read
  // routing gates separately, on the placement having converged; do not reuse
  // this RPC to answer "where may I read this repo from". An ungrouped repo
  // resolves to home = its own placement with no mirrors of either kind. A
  // GitHub mirror group resolves the same way unless one of its placements
  // owns the group's git data, in which case home is that owner and the
  // siblings come back as namespace_mirrors (see below); full-repo GitHub
  // mirroring still routes through LookupByMirror, not here. CodeNotFound
  // when the repo id is unknown; CodeInvalidArgument when it is empty or not
  // a ULID.
  rpc LookupNativeMirrorsByRepoID(LookupNativeMirrorsByRepoIDRequest) returns (LookupNativeMirrorsByRepoIDResponse);
}

message LookupByMirrorRequest {
  // Upstream provider, e.g. "github". Required.
  string provider = 1;

  // Upstream owner segment (org or user), e.g. "octocat". Required.
  string owner = 2;

  // Upstream repo name, e.g. "hello-world". Required.
  string repo = 3;

  // GitHub's immutable numeric repo id, from the webhook's repository.id.
  // Optional; 0 means unknown. When set, only placements of that upstream are
  // returned: owner/repo can be stale on our side (a teardown leaked, then the
  // owner renamed away) and claimed by another GitHub account, whose events
  // must not route onto the old mirror (ENT-2822).
  int64 github_repo_id = 4;
}

message LookupByMirrorResponse {
  repeated Placement placements = 1;
}

message LookupMirrorByIDRequest {
  // Crockford Base32 ULID of the mirrored repo within EntireDB. Required.
  string repo_id = 1;
}

message LookupMirrorByIDResponse {
  // Upstream provider, e.g. "github". Always "github" today — mirror_repos
  // joins github_repos for its upstream coordinates.
  string provider = 1;

  // Upstream owner segment (org or user), e.g. "octocat".
  string owner = 2;

  // Upstream repo name, e.g. "hello-world".
  string repo = 3;
}


  // The home cluster's INTERNAL by-ID git URL for the primary
  // (https://<internal host>/git/repo/<primary ULID>) — the sync job's
  // fetch source. Empty when the home cluster has no internal URL
  // registered. Never user-facing.
  string source_url = 3;

  // Namespace-mirror placements: the other ready placements of a GitHub
  // group whose git data is owned by one of them (COR-1566). They receive
  // entiredb_ns sync jobs, which replicate ONLY the Entire-owned
  // refs/heads/entire/native/* namespace from source_url — the rest of
  // their ref state comes from GitHub. Ordered by (jurisdiction,
  // cluster_slug); empty for every group without an owner, and never
  // populated together with native_mirrors (a group is one kind or the
  // other).
  repeated Placement namespace_mirrors = 4;
}

