// Package repolookup implements the internal mTLS Connect-RPC that resolves
// upstream mirror coordinates to every (jurisdiction, cluster_slug) hosting
// the mirror. It is the routing primitive for ADR 20260408's per-cluster
// NATS subjects: webhook ingest receives one upstream event and asks core
// where the mirror lives across the fleet so it can fan out the job.
//
// Reads come from mirror_repos via core/mirrorrepo; webhook fan-out
// only reaches mirrors registered there.
//
// The handler performs no SpiceDB authz — workload-allowlist enforcement
// happens at the receiver-side mTLS middleware (core/servicetoken/server).
// End-user identity is intentionally absent from this surface.
package repolookup

import (
	"context"
	"errors"
	"fmt"
	"log/slog"

	"connectrpc.com/connect"

	"entire.io/core/mirrorrepo"
	"entire.io/core/model"
	"entire.io/core/nativemirror"
	pb "entire.io/gen/proto/internalapi/repolookup/v1"
	"entire.io/slogutil"
)

// Mirrors is the slice of [mirrorrepo.Service] this handler uses. Kept
// as an interface so test fakes can satisfy it without spinning up the
// full DB-backed service.
type Mirrors interface {
	FindPlacements(ctx context.Context, provider, owner, repo string) ([]mirrorrepo.Placement, error)
	GetRefByID(ctx context.Context, id model.RepoID) (*mirrorrepo.Ref, error)
}

// NativeMirrors is the slice of [nativemirror.Service] behind the native
// native-mirror-routing RPCs. Interface for the same test-fake reason as Mirrors.
type NativeMirrors interface {
	ResolveRouting(ctx context.Context, repoID model.RepoID) (nativemirror.Routing, error)
}

// ConnectHandler implements the Connect-RPC RepoLookupHandler interface.
type ConnectHandler struct {
	mirrors       Mirrors
	nativeMirrors NativeMirrors
}

func NewConnectHandler(mirrors Mirrors, nativeMirrors NativeMirrors) *ConnectHandler {
	return &ConnectHandler{mirrors: mirrors, nativeMirrors: nativeMirrors}
}

func routingPlacementToWire(p nativemirror.RoutingPlacement) *pb.Placement {
	return &pb.Placement{
		RepoId:       p.RepoID.String(),
		Jurisdiction: p.Jurisdiction,
		ClusterSlug:  p.ClusterSlug,
	}
}

func (h *ConnectHandler) LookupNativeMirrorsByRepoID(ctx context.Context, req *connect.Request[pb.LookupNativeMirrorsByRepoIDRequest]) (*connect.Response[pb.LookupNativeMirrorsByRepoIDResponse], error) {
	repoID, err := model.ParseRepoID(req.Msg.GetRepoId())
	if err != nil {
		return nil, connect.NewError(connect.CodeInvalidArgument, errors.New("repo_id must be a valid ULID"))
	}
	routing, err := h.nativeMirrors.ResolveRouting(ctx, repoID)
	if errors.Is(err, nativemirror.ErrNotFound) {
		return nil, connect.NewError(connect.CodeNotFound, errors.New("no repo registered for repo_id"))
	}
	if err != nil {
		slogutil.Error(ctx, "repolookup: resolve native-mirror routing failed",
			slog.String("repo_id", repoID.String()),
			slog.String("error", err.Error()))
		return nil, connect.NewError(connect.CodeUnavailable, errors.New("lookup failed"))
	}
	resp := &pb.LookupNativeMirrorsByRepoIDResponse{
		Home:             routingPlacementToWire(routing.Home),
		SourceUrl:        routing.SourceURL,
		NativeMirrors:    make([]*pb.Placement, 0, len(routing.NativeMirrors)),
		NamespaceMirrors: make([]*pb.Placement, 0, len(routing.NamespaceMirrors)),
	}
	for _, r := range routing.NativeMirrors {
		resp.NativeMirrors = append(resp.NativeMirrors, routingPlacementToWire(r))
	}
	for _, r := range routing.NamespaceMirrors {
		resp.NamespaceMirrors = append(resp.NamespaceMirrors, routingPlacementToWire(r))
	}
	return connect.NewResponse(resp), nil
}

func (h *ConnectHandler) LookupByMirror(ctx context.Context, req *connect.Request[pb.LookupByMirrorRequest]) (*connect.Response[pb.LookupByMirrorResponse], error) {
	provider, owner, repo := req.Msg.GetProvider(), req.Msg.GetOwner(), req.Msg.GetRepo()
	if provider == "" || owner == "" || repo == "" {
		return nil, connect.NewError(connect.CodeInvalidArgument, errors.New("provider, owner, and repo are required"))
	}

	placements, err := h.mirrors.FindPlacements(ctx, provider, owner, repo)
	if err != nil {
		slogutil.Error(ctx, "repolookup: find mirror placements failed",
			slog.String("provider", provider),
			slog.String("owner", owner),
			slog.String("repo", repo),
			slog.String("error", err.Error()))
		return nil, connect.NewError(connect.CodeUnavailable, errors.New("lookup failed"))
	}

	resp := &pb.LookupByMirrorResponse{
		Placements: make([]*pb.Placement, 0, len(placements)),
	}
	for _, p := range placements {
		if p.ClusterSlug == "" {
			// mirror_repos.cluster_slug is NOT NULL, so this can only
			// happen if a buggy fake returns empty strings — surface a
			// warning rather than silently ship an unroutable record.
			slogutil.Warn(ctx, "repolookup: dropping placement with empty cluster_slug",
				slog.String("provider", provider),
				slog.String("owner", owner),
				slog.String("repo", repo),
				slog.String("mirror_repo_id", p.MirrorRepoID.String()),
				slog.String("jurisdiction", p.Jurisdiction))
			continue
		}
		if githubRepoID := req.Msg.GetGithubRepoId(); githubRepoID != 0 && p.GitHubRepoID != githubRepoID {
			// The name matched but the upstream didn't: our github_repos row
			// holds a stale owner/repo that another GitHub repo now answers
			// to (ENT-2822). Never route its events onto this mirror.
			slogutil.Warn(ctx, "repolookup: dropping placement of a different upstream with the same owner/repo",
				slog.String("provider", provider),
				slog.String("owner", owner),
				slog.String("repo", repo),
				slog.String("mirror_repo_id", p.MirrorRepoID.String()),
				slog.Int64("placement_github_repo_id", p.GitHubRepoID),
				slog.Int64("event_github_repo_id", githubRepoID))
			recordUpstreamMismatch(ctx)
			continue
		}
		resp.Placements = append(resp.Placements, &pb.Placement{
			RepoId:       p.MirrorRepoID.String(),
			Jurisdiction: p.Jurisdiction,
			ClusterSlug:  p.ClusterSlug,
		})
	}
	return connect.NewResponse(resp), nil
}

