package projectdirectory

import (
	"context"
	"fmt"
	"log/slog"

	"entire.io/core/model"
	"entire.io/slogutil"
)

type Store interface {
	ListProjectsByIDs(ctx context.Context, ids []model.ProjectID) ([]*model.Project, error)
}

// CellRegistry lists the slugs of clusters currently serving a jurisdiction.
// *api.Server satisfies this; the interface keeps projectdirectory free of
// core/api.
//
// It backs the DEPRECATED ProcessingCellSlug only. The stored assignment never
// consults it, and it goes away with that field.
type CellRegistry interface {
	ClusterSlugsForJurisdiction(ctx context.Context, jurisdiction string) ([]string, error)
}

type ResolvedProject struct {
	ID           model.ProjectID
	Name         string
	OwnerType    string
	Jurisdiction string
	// ProcessingCellSlug is the DEPRECATED cluster slug derived from
	// Jurisdiction. See the proto field for the deprecation contract.
	ProcessingCellSlug string
	// PrimaryProcessingCell is the project's stored cell assignment, empty
	// when the project predates it. A cell id, never a cluster slug.
	PrimaryProcessingCell string
}

type Resolver struct {
	store Store
	cells CellRegistry
}

func New(store Store, cells CellRegistry) *Resolver {
	return &Resolver{store: store, cells: cells}
}

// cellMemo resolves a jurisdiction to its processing cell, memoized for one
// batch. Anything but exactly one serving cluster yields an empty slug: zero
// means nothing can host the project's trails, and more than one means the
// registry cannot say which would, so guessing would silently home trails on
// the wrong cell.
//
// This is the DEPRECATED derivation, kept bug-for-bug while consumers move to
// the stored assignment. Do not extend it, and never let the stored assignment
// fall back to it — that derivation is what
// ADR 20260909-project-primary-processing-cell replaces.
func (r *Resolver) cellMemo(ctx context.Context) func(jurisdiction string) string {
	cache := make(map[string]string)
	return func(jurisdiction string) string {
		if s, ok := cache[jurisdiction]; ok {
			return s
		}
		slug := ""
		slugs, err := r.cells.ClusterSlugsForJurisdiction(ctx, jurisdiction)
		switch {
		case err != nil:
			slogutil.Warn(ctx, "cluster registry unreadable; project will have empty processing_cell_slug",
				slog.String("jurisdiction", jurisdiction), slog.Any("error", err))
		case len(slugs) == 1:
			slug = slugs[0]
		default:
			slogutil.Warn(ctx, "jurisdiction does not map to exactly one serving cluster; project will have empty processing_cell_slug",
				slog.String("jurisdiction", jurisdiction), slog.Int("clusters", len(slugs)))
		}
		cache[jurisdiction] = slug
		return slug
	}
}

