// (COR-932): it decrypts a legacy token and hands entire-core the
// plaintext to re-encrypt and store in the global github_user_tokens
// table, so pre-migration users stop hitting "GitHub authorization
// expired" without re-authing. entire-core keeps all KMS + global-DB
// access; the importer never touches KMS. Insert-if-absent so a token
// the user has since re-created by re-authing is never clobbered.
// Gated to the entire-api workload like the account reads above; nil
// githubTokens (no cipher configured) simply leaves the route unmounted.
if deps.identitySvc != nil && deps.githubTokens != nil {
	internalMux.Handle("POST /github-tokens/seed",
		githubTokensSeedAuthMiddleware(cfg.Domain)(
			githubTokenSeedHandler(deps.identitySvc, deps.githubTokens)))
}

// Commit-author email -> Entire account + external identities, read
// at ingest to attribute commit authors (COR-659 / COR-660). The
// regional resolver (verified_emails + handles + the github no-reply
// parse) sits behind an in-process LRU. Two consumers — entire-api
// (checkpoints/sessions render) and entire-search (the semantic-search
// index's author field) — so this has its own gate rather than the
// API-only accountsAuthMiddleware. Kept off the public surface since it
// maps emails (PII) to account residency.
// regionalSvc is wired in regional mode (the only mode this
// listener activates for), so the nil check is defensive, not
// a mode switch.
if deps.regionalSvc != nil {
	authorCache := newAuthorAccountsCache(authorAccountsCacheTTL, deps.regionalSvc)
	internalMux.Handle("POST /author-accounts",
		authorAccountsAuthMiddleware(cfg.Domain)(authorAccountsHandler(authorCache)))
}

// Repo metadata by id, read by entire-api to hydrate ingested ref
// events with repo context (COR-593). Mirrors the public
// GET /repos/{id} body via coreapi.RepoService, minus per-repo
// authz — access control is purely the workload gate at this mTLS
// boundary, same as /accounts/{id}.
if apiSrv != nil {
	internalMux.Handle("GET /repos/{id}",
		reposAuthMiddleware(cfg.Domain)(repoByIDHandler(&coreapi.RepoService{Server: apiSrv})))

	// The public route's path, read by entire-ci-webhooks to
	// rebuild its installation projection. No user stands behind
	// that read, so the workload certificate is the whole
	// authorization.
	internalMux.Handle("GET /api/v1"+coreapi.GetPluginInstallationPath,
		pluginInstallationReadAuthMiddleware(cfg.Domain)(
			coreapi.NewPluginInstallationReadHandler(apiSrv)))
	internalMux.Handle("GET /api/v1"+coreapi.GetPluginPath,
		pluginReadAuthMiddleware(cfg.Domain)(coreapi.NewPluginReadHandler(apiSrv.PluginCatalog())))

	// Batch repo-name resolve, the tier-2 companion entire-api's /me
	// resolver calls for activity on a repo with no placement in the
	// reader cell. Unlike the reads above, the workload gate is only
	// the mTLS pipe: authorization is the caller's forwarded bearer,
	// verified into claims and gated per repo on pull, so a name is
	// revealed only for a repo the end user can pull — never on
	// entire-api's workload identity alone.
	internalMux.Handle("POST /repos/names",
		repoNamesAuthMiddleware(cfg.Domain)(
			forwardedBearerClaims(apiSrv)(
				repoNamesHandler(&coreapi.RepoService{Server: apiSrv}))))

	// Mirror resync trigger (ENT-1172): entire-api calls this when a
	// code repo with a separate external checkpoints repo gets a
	// branch/tag push, so the checkpoints repo — which GitHub emits
	// no webhook for (pushes outside refs/heads|tags) — still syncs
	// into entiredb. The handler resolves the mirror placement id to
	// GitHub coords and publishes a synthetic push webhook to the
	// central webhooks_github_v1 stream, where mirror-pipeline's
	// fanout picks it up. {id} is the mirror placement's repo ULID,
	// same as the /api/admin/mirrors/{id}/… ops. Checkpoint-agnostic:
	// it just resyncs the given mirror.
	internalMux.Handle("POST /mirrors/{id}/resync",
		resyncAuthMiddleware(cfg.Domain)(resyncByIDHandler(apiSrv)))
}

// Automation-principal CRUD (ADR 20260728-automation-principal):
// ID-addressed create/upsert, list, get, delete, and per-automation
// grant/binding management. Production callers: entire-api's runner
// reconciler (internal/runnerreconcile) and its Depot bindings; a
// comment here once said "no production caller" and #3584 broke
// runner declarations for seventy minutes on that belief. automationSvc
// and resourceSvc are wired together in regional mode (the only
// mode this listener activates for), so the nil check is
// defensive, not a mode switch.
if deps.automationSvc != nil && deps.resourceSvc != nil && deps.authzSvc != nil {
	internalMux.Handle("POST /automations",
		automationsAuthMiddleware(cfg.Domain)(
			automationsUpsertHandler(deps.automationSvc, deps.resourceSvc, deps.authzSvc)))
	internalMux.Handle("GET /repo-groups/{groupID}/automations",
		automationsAuthMiddleware(cfg.Domain)(

