// allowCacheTTL bounds how long a stale ALLOW survives in the positive cache —
// i.e. how long a revoked grant keeps authorizing after SpiceDB would deny it.
// Core's caches over SpiceDB checks (platformAdminCache, HandleStateCache)
// invalidate eagerly on the in-process grant/revoke that changed the answer;
// the data plane has no such event (grants/revokes happen in core), so this
// TTL is the entire revocation window — there is no shorter bound. Kept to the
// platform-admin precedent's 30s; it sits well inside the token lifetime that
// already bounds revocation on the git path.
const allowCacheTTL = 30 * time.Second

// allowCacheSize caps the LRU. The key space is (account, repo, action), which
// can be large on a busy cluster, so this is generous; eviction is LRU.
const allowCacheSize = 16384

// allowKey is the ALLOW cache key — the (account, repo, action) the decision
// was made for. A typed struct (matching core's handleKey) keeps the field set
// explicit and comparable, avoiding a hand-built delimited string.
type allowKey struct {
	account string
	repo    string
	action  string
}

// String is the singleflight group key — singleflight needs a string, so the
// key derives from the same struct rather than a second hand-built form.
func (k allowKey) String() string {
	return k.account + "|" + k.repo + "|" + k.action
}

// RepoAuthorizer is the single repo-authorization decision point shared by the
// huma repo API and the git smart-HTTP routes. It bridges the two principal
// models a request can arrive with:
//
//   - Per-repo scoped JWTs (and backup/peer credentials): the authorization
//     decision is carried in the token, stamped by the authorizing core at
//     issuance. Reproduced offline via reqctx.Principal.PermitsGit — no
//     network call, no SpiceDB dependency.
//   - Account access tokens (ADR 20260729): the token conveys identity only,
//     so authority is resolved live against the regional read-only SpiceDB
//     per request via the authz.Reader. The subject is always the verified caller's account —
//     never request input.
//
// Live ALLOW results are memoized in a short-TTL LRU (allowCache) so the hot
// git path doesn't re-query SpiceDB for every operation by the same caller.
// Only allows are cached: a cached deny would defeat Reader.Can's
// deny-recheck-at-full-consistency (a just-granted permission would be stuck
// behind a stale deny), so denies always re-query. The only staleness the
// cache adds is bounded over-permission after a revocation — at most
// allowCacheTTL.
//
// The cache value is the entry's expiry instant; TTL is enforced lazily on
// read (cachedAllow), NOT by a background eviction goroutine. This matters:
// the data plane is exercised inside synctest simulation bubbles, and a timer
// loop that never exits (expirable.LRU's) would leave a blocked goroutine in
// the bubble and deadlock the harness.
//
// Concurrent cold misses for the same (account, repo, action) — a burst of
// identical first-checks, e.g. a CI runner's parallel fetches — are collapsed
// by a singleflight group into one SpiceDB check; the coalesced callers all
// receive that one fresh result. This adds no staleness (unlike the cache):
// it only de-duplicates in-flight work.
type RepoAuthorizer struct {
	reader     PermissionReader
	allowCache *lru.Cache[allowKey, time.Time]
	flight     singleflight.Group
}

// PermissionReader is the one-method slice of authz.Reader the authorizer
// depends on. Production passes the SpiceDB-backed *authz.Reader; the
// integration testserver injects an in-process fake so account access tokens can be
// authorized without a SpiceDB.
type PermissionReader interface {
	Can(ctx context.Context, subject authz.Subject, action authz.Action, resource authz.Resource) (bool, error)
}

// NewRepoAuthorizer builds a RepoAuthorizer over the process-shared
// authz.Reader (the regional read-only SpiceDB client dialed once at startup).
func NewRepoAuthorizer(reader PermissionReader) *RepoAuthorizer {
	if reader == nil {
		panic("authz: RepoAuthorizer requires a SpiceDB permission reader")
	}
	// lru.New only errors on a non-positive size; allowCacheSize is a positive
	// constant, so this never fails.
	cache, err := lru.New[allowKey, time.Time](allowCacheSize)
	if err != nil {
		panic(fmt.Sprintf("authz: build allow cache: %v", err))
	}
	return &RepoAuthorizer{reader: reader, allowCache: cache}
}

// cachedAllow reports whether key holds an unexpired ALLOW. An expired entry is
// evicted so it doesn't linger (TTL is enforced here, not by a timer).
func (a *RepoAuthorizer) cachedAllow(key allowKey) bool {
	exp, ok := a.allowCache.Get(key)
	if !ok {
		return false
	}
	if !time.Now().Before(exp) {
		a.allowCache.Remove(key)
		return false
	}
	return true
}

