// repo named by repoID, the ULID the data plane resolved the request to.
//
// The return contract distinguishes the three outcomes callers must render
// differently:
//
//   - (true, nil):  allow.
//   - (false, nil): deny — caller renders 403.
//   - (false, err): the decision could not be reached (SpiceDB error,
//     misconfiguration, unknown action). Caller renders 503 and never
//     proceeds — fail closed.
//
// For account access tokens the decision is served from the short-TTL ALLOW
// cache when present; otherwise the live check runs at
// minimize_latency and, on a deny only, re-checks at full consistency
// (authz.Reader.Can) so a recent grant not yet on the regional replica isn't a
// false 403. Only allows are cached (see the type doc).
func (a *RepoAuthorizer) Authorize(ctx context.Context, p reqctx.Principal, repoID, action string) (bool, error) {
	if p.Kind != reqctx.TokenLoginJWT && p.Kind != reqctx.KindAutomation {
		// Scoped / backup / peer tokens carry the decision in the token.
		return p.PermitsGit(repoID, action), nil
	}
	subject, err := authzSubjectForPrincipal(p)
	if err != nil {
		return false, err
	}
	act, err := gitActionToSpiceDB(action)
	if err != nil {
		return false, err
	}
	key := allowKey{account: p.Subject.String(), repo: repoID, action: action}
	if a.cachedAllow(key) {
		return true, nil
	}
	// Collapse concurrent cold misses for this key into one SpiceDB check.
	// Followers block here and receive the leader's fresh result; only the
	// leader queries Reader.Can and populates the cache.
	v, err, _ := a.flight.Do(key.String(), func() (any, error) {
		// The leader may have populated the cache between our miss and our
		// turn in the flight.
		if a.cachedAllow(key) {
			return true, nil
		}
		allowed, cerr := a.reader.Can(ctx, subject, act, authz.Repo(repoID))
		if cerr != nil {
			return false, fmt.Errorf("authz: repo %s check: %w", action, cerr)
		}
		if allowed {
			a.allowCache.Add(key, time.Now().Add(allowCacheTTL))
		}
		return allowed, nil
	})
	if err != nil {
		return false, err //nolint:wrapcheck // already wrapped inside the flight func
	}
	allowed, ok := v.(bool)
	if !ok {
		return false, fmt.Errorf("authz: unexpected flight result %T", v)
	}
	return allowed, nil
}

// authzSubjectForPrincipal builds the SpiceDB subject to check for a
// principal authorized live (account access or automation) — never assume a
// bare account. An account access token's subject is always the verified
// caller's account; an automation token's
// subject is the automation itself (ADR 20260728-automation-principal), which
// holds no account id at all.
func authzSubjectForPrincipal(p reqctx.Principal) (authz.Subject, error) {
	if automationID, ok := p.Subject.Automation(); ok {
		return authz.AutomationSubject(automationID), nil
	}
	accountID, ok := p.Subject.AccountID()
	if !ok {
		return authz.Subject{}, fmt.Errorf("authz: principal (kind %s) carries no subject to authorize", p.Kind)
	}
	return authz.AccountSubject(accountID), nil
}

