// against repo:<mirror_repos.id>. Two things still differ from the native
// path:
//
//   - resolution: the slug is looked up in github_mirror_repo_urls
//     under the audience host's cluster (per-cluster URL space, not
//     the global repo_urls), and the audience-host vs. resource-cluster
//     coupling is enforced by the lookup itself — "no row in this
//     cluster" is the failure, not a separate audience-host check.
//   - public-pull short-circuit: a public upstream
//     (github_repos.is_private = false) may be cloned by anyone who can
//     reach the cluster, matching GitHub's own visibility and the
//     behaviour the legacy githubperms.CanPull gate had. Private
//     upstreams and every push fall through to the SpiceDB check.
//
// The issued JWT stamps repo_id = mirror_repos.id, which entire-server
// addresses storage by — the same shape native repos use, so the data
// plane doesn't need to know whether it's serving a mirror.
//
// SpiceDB denial: refused as invalid_target ("no mirror at this URL"), the
// same refusal a missing mirror gets, so it isn't an enumeration oracle for
// private mirrors with public GitHub coords (ENT-1021). This matches the
// native path (validateRepoExchange) and refuseSuspendedMirror.
//
// A suspended mirror is also refused as invalid_target, but
// with an actionable description — suspended-since plus the resume
// command — for callers the SpiceDB gate (or the public short-circuit)
// would otherwise admit. Callers who fail that gate get the same "no
// mirror at this URL" a missing mirror gets, so suspension discloses
// nothing new (see refuseSuspendedMirror).
func (s *Storage) validateMirrorRepoExchange(ctx context.Context, req op.TokenExchangeRequest, shape authn.AudienceShape, subjectScopes []authn.Scope, acct *exchangeAccount) error {
	if !authn.HasScope(subjectScopes, authn.ScopeEntireRepoAccess) {
		return oidc.ErrInvalidGrant().WithDescription("subject_token may not exchange for a repo-access token")
	}
	if shape.RepoSlug == "" {
		return oidc.ErrInvalidTarget().WithDescription("mirror audience must include a /gh/ path slug")
	}
	if s.mirrorResolver == nil {
		return oidc.ErrInvalidTarget().WithDescription("mirror token exchange not configured")
	}
	if s.clusterResolver == nil {
		return oidc.ErrInvalidTarget().WithDescription("cluster registry not configured")
	}

	action, err := requestedRepoAction(req)
	if err != nil {
		return err
	}

	clusterSlug, err := s.clusterResolver.ClusterSlugByHost(ctx, shape.Host)
	if err != nil {
		if errors.Is(err, ErrClusterNotFound) {
			return oidc.ErrInvalidTarget().WithDescription("audience host is not a registered cluster")
		}
		return fmt.Errorf("resolve cluster by host: %w", err)
	}

	ref, err := s.mirrorResolver.LookupMirrorRefByURL(ctx, clusterSlug, authn.CanonicalizeRepoURL(shape.RepoSlug))
	if err != nil {
		if suspended, ok := errors.AsType[*MirrorSuspendedError](err); ok {
			return s.refuseSuspendedMirror(ctx, req, action, suspended)
		}
		if errors.Is(err, ErrMirrorNotFound) {
			return s.refuseReleasedMirror(ctx, req, shape)
		}
		return fmt.Errorf("resolve mirror: %w", err)
	}

	allowed, err := s.checkMirrorAccess(ctx, req.GetSubject(), action, ref)
	if err != nil {
		return err
	}
	if !allowed {
		// Fold denial into the same not-found a missing mirror gets — matching
		// the native path (validateRepoExchange → errRepoTargetNotFound) and
		// refuseSuspendedMirror — so a caller without access can't tell an
		// existing private mirror apart from a missing one (ENT-1021). This is
		// not a session error, so it must not surface as access_denied (which
		// the CLI treats as a re-login prompt); a permission denial is not
		// fixable by re-login anyway.
		return errMirrorTargetNotFound()
	}

	if err := acct.assertApproved(ctx); err != nil {
		return err
	}
	req.SetCurrentScopes([]string{string(action)})
	// Stamp the validated mirror ULID; the claim hook reads from this
	// same map so the repo_id baked into the JWT is the one authz
	// approved, not a re-resolution that could race a URL alias write.
	s.exchangeRepoIDs.Store(req, ref.MirrorRepoID.String())
	return nil
}

// errMirrorTargetNotFound is the uniform refusal for a mirror slug the
// caller may not learn anything about: genuinely absent, or suspended
// but the caller doesn't pass the perms gate. One constructor so the
// two cases can never drift apart and become distinguishable.
func errMirrorTargetNotFound() error {
	return oidc.ErrInvalidTarget().WithDescription("no mirror at this URL")
}

