	}

	if err := acct.assertApproved(ctx); err != nil {
		return err
	}
	req.SetCurrentScopes([]string{string(action)})
	// Stamp the validated mirror ULID; the claim hook reads from this
	// same map so the repo_id baked into the JWT is the one authz
	// approved, not a re-resolution that could race a URL alias write.
	s.exchangeRepoIDs.Store(req, ref.MirrorRepoID.String())
	return nil
}

// errMirrorTargetNotFound is the uniform refusal for a mirror slug the
// caller may not learn anything about: genuinely absent, or suspended
// but the caller doesn't pass the perms gate. One constructor so the
// two cases can never drift apart and become distinguishable.
func errMirrorTargetNotFound() error {
	return oidc.ErrInvalidTarget().WithDescription("no mirror at this URL")
}

