func loadProjectTrailListPage(ctx context.Context, deps *RepoActivityDeps, scopes []store.ProjectTrailProjectScope, filters store.ProjectTrailFilters, pageSize int, cursor *store.ProjectTrailCursor) (projectTrailListPage, error) {
	result, err := deps.Store.ListGlobalProjectTrailPage(ctx, scopes, pageSize+1, cursor, filters)
	if err != nil {
		return projectTrailListPage{}, projectTrailStoreError("store: list project Trail page", err)
	}
	page := projectTrailListPage{Rows: result.Rows, Counts: result.Counts}
	if len(page.Rows) > pageSize {
		page.NextRow = &page.Rows[pageSize]
		page.Rows = page.Rows[:pageSize]
	}
	return page, nil
}

